// No controlado: el DOM guarda el valor; se lee al enviar
function NoControlado() {
  const formRef = useRef(null);
  return (
    <form ref={formRef} onSubmit={(e) => {
      e.preventDefault();
      const datos = Object.fromEntries(new FormData(formRef.current));
    }}>
      <input name="bultos" />
      <button>Enviar</button>
    </form>
  );
}

// Controlado: el estado de React guarda el valor; cada tecla pasa por onChange
function Controlado() {
  const [bultos, setBultos] = useState('');
  const soloDigitos = (v) => v.replace(/\D/g, '');
  return <input value={bultos} onChange={(e) => setBultos(soloDigitos(e.target.value))} />;
}

