// El esquema: una sola descripción de «qué es un pedido válido», compartida por el navegador y el servidor
import { z } from 'zod';

export const Pedido = z.object({
  cliente: z.string().trim().min(2, 'Escribí el nombre del cliente').max(80, 'Máximo 80 letras'),
  bultos: z.string().trim()
    .regex(/^\d+$/, 'Escribí un número entero, sin puntos ni espacios')
    .transform(Number)
    .pipe(z.number().min(1, 'Mínimo 1 bulto').max(500, 'Máximo 500 bultos')),
  email: z.email('Ese mail no parece válido'),
  deposito: z.enum(['avellaneda', 'pompeya'], 'Elegí un depósito'),
});

export const errores = (entrada) => {
  const r = Pedido.safeParse(entrada);
  return r.success ? { datos: r.data } : { errores: z.flattenError(r.error).fieldErrors };
};

